[InlineArray(16)]
struct SmallBytes
{
    private byte _first;          // the runtime replicates this field 16 times
}
static int Store(ReadOnlySpan<byte> payload, ref SmallBytes inlineBuf)
{
    Span<byte> buf = inlineBuf;                     // view over the in-object storage
    if (payload.Length > buf.Length) return Spill(payload);   // ArrayPool<byte>.Shared.Rent
    payload.CopyTo(buf);                            // small case: no allocation
    return payload.Length;
}
